/* Minimal Panda-shaped fixture for composition-derived bans. */
type TextStyleProperty =
  | 'fontSize'
  | 'fontWeight'
  | 'lineHeight'
  | 'letterSpacing'
  | 'textTransform'
export type TextStyles = unknown;

type LayerStyleProperty =
  | 'background'
  | 'backgroundColor'
  | 'borderColor'
  | 'boxShadow'
  | 'opacity'
export type LayerStyles = unknown;
